import{_ as e,o as s,c as n,a0 as t}from"./chunks/framework.BpJS36ta.js";const m=JSON.parse('{"title":"Export","description":"","frontmatter":{},"headers":[],"relativePath":"syntax/export.md","filePath":"syntax/export.md"}'),p={name:"syntax/export.md"};function i(o,a,r,d,l,c){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h1><p>Export deklarasi dari file agar bisa di-import oleh file lain.</p><h2 id="bentuk-kanonik" tabindex="-1">Bentuk kanonik <a class="header-anchor" href="#bentuk-kanonik" aria-label="Permalink to &quot;Bentuk kanonik&quot;">​</a></h2><p>Hanya ada <strong>dua bentuk export</strong> yang jadi standar bahasa:</p><h3 id="_1-semua-member-—-export-from-x" tabindex="-1">1. Semua member — <code>export * from ./X</code> <a class="header-anchor" href="#_1-semua-member-—-export-from-x" aria-label="Permalink to &quot;1. Semua member — \`export * from ./X\`&quot;">​</a></h3><p>Ekspor semua yang ada di X (flatten). Policy tetap bisa menyertai:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>export * from ./X</span></span>
<span class="line"><span>export * from ./X -&gt; { secret: private }</span></span></code></pre></div><p>Member yang di-mark <code>private</code> diterbitkan sebagai <code>null</code> dan dicatat di <code>_private</code> — tidak bisa dipanggil dari luar.</p><h3 id="_2-selective-—-export-x-y-from-x" tabindex="-1">2. Selective — <code>export x, y from ./X</code> <a class="header-anchor" href="#_2-selective-—-export-x-y-from-x" aria-label="Permalink to &quot;2. Selective — \`export x, y from ./X\`&quot;">​</a></h3><p>Ekspor hanya <code>x</code> dan <code>y</code> dari X:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// file modules/math.rp</span></span>
<span class="line"><span>add(a, b) { return a + b }</span></span>
<span class="line"><span>sub(a, b) { return a - b }</span></span>
<span class="line"><span>mul(a, b) { return a - b }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// file index.rp — hanya export add dan sub</span></span>
<span class="line"><span>export add, sub from ./math</span></span></code></pre></div><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import add, sub from ./index</span></span>
<span class="line"><span>print(add(2, 3))  // 5</span></span>
<span class="line"><span>print(sub(5, 2))  // 3</span></span>
<span class="line"><span>// mul tidak bisa di-import — tidak di-export</span></span></code></pre></div><h3 id="re-export-dengan-nama-—-export-name-from-path" tabindex="-1">Re-export dengan nama — <code>export name from ./path</code> <a class="header-anchor" href="#re-export-dengan-nama-—-export-name-from-path" aria-label="Permalink to &quot;Re-export dengan nama — \`export name from ./path\`&quot;">​</a></h3><p>Satu nama polos mengikat <strong>member bernama sama</strong> bila ada di module sumber (mis. fungsi <code>open</code> di <code>open.rp</code>), selain itu mengikat <strong>seluruh module</strong> sebagai namespace — bentuk ini yang merangkai pohon package:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// file index.rp</span></span>
<span class="line"><span>export math_utils from ./math    // math.rp → namespace math_utils</span></span>
<span class="line"><span>export view from ./view          // sub-package → member pohon</span></span></code></pre></div><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import math_utils from ./index</span></span>
<span class="line"><span>print(math_utils.add(2, 3))  // 5</span></span></code></pre></div><blockquote><p>Nama namespace (<code>math_utils</code>) tidak harus sama dengan nama file (<code>math.rp</code>).</p></blockquote><h2 id="policy-—-item-private" tabindex="-1">Policy — <code>-&gt; { item: private }</code> <a class="header-anchor" href="#policy-—-item-private" aria-label="Permalink to &quot;Policy — \`-&gt; { item: private }\`&quot;">​</a></h2><p>Mengontrol akses item pada re-export namespace:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// file modules/auth.rp</span></span>
<span class="line"><span>login(user, pass) { ... }</span></span>
<span class="line"><span>register(user, pass) { ... }</span></span>
<span class="line"><span>hashPassword(pass) { ... }   // internal — tidak boleh diakses luar</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// file index.rp</span></span>
<span class="line"><span>export auth from ./auth -&gt; { hashPassword: private }</span></span></code></pre></div><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import auth from ./index</span></span>
<span class="line"><span>auth.login(&quot;admin&quot;, &quot;123&quot;)      // ✅ works</span></span>
<span class="line"><span>auth.register(&quot;user&quot;, &quot;456&quot;)    // ✅ works</span></span>
<span class="line"><span>auth.hashPassword(&quot;secret&quot;)     // ❌ PrivateError: &#39;hashPassword&#39; is private and cannot be called from outside</span></span></code></pre></div><p>Policy boleh ditulis multi-line — blok <code>-&gt; {</code> dibuka di akhir statement dan isi diletakkan di baris berikutnya:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// file index.rp</span></span>
<span class="line"><span>export auth from ./auth -&gt; {</span></span>
<span class="line"><span>  hashPassword: private</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Kedua bentuk (single-line dan multi-line) berperilaku identik.</p><h2 id="namespace-—-namespace-name" tabindex="-1">Namespace — <code>namespace name { ... }</code> <a class="header-anchor" href="#namespace-—-namespace-name" aria-label="Permalink to &quot;Namespace — \`namespace name { ... }\`&quot;">​</a></h2><p>Namespace mengelompokkan export ke dalam satu object namespace:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>namespace db {</span></span>
<span class="line"><span>  export driver from ./driver</span></span>
<span class="line"><span>  export dsn from ./dsn</span></span>
<span class="line"><span>}</span></span></code></pre></div><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import db from rupa</span></span>
<span class="line"><span>db.driver.has(&quot;sqlite&quot;)</span></span></code></pre></div><blockquote><p>Nama directory/package tidak harus sama dengan nama namespace yang diekspor.</p></blockquote><h2 id="package-tree-export" tabindex="-1">Package &amp; Tree Export <a class="header-anchor" href="#package-tree-export" aria-label="Permalink to &quot;Package &amp; Tree Export&quot;">​</a></h2><p>Package adalah directory dengan <code>index.rp</code>. File leaf (selain <code>index.rp</code>) <strong>tidak wajib export</strong> — cukup berisi kode. Ia hanya bisa dijangkau melalui rantai index-nya, tidak pernah langsung dari luar package.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rpx_engine/</span></span>
<span class="line"><span>├── index.rp            export view from ./view</span></span>
<span class="line"><span>└── view/</span></span>
<span class="line"><span>    ├── index.rp        export resources from ./resources -&gt; { load: private }</span></span>
<span class="line"><span>    └── resources.rp    leaf — tanpa export, cukup berisi kode</span></span></code></pre></div><p>Index berperan sebagai node cabang pohon: <code>view/index.rp</code> mengekspos isi leaf-nya, <code>index.rp</code> induk mengekspos sub-package-nya. Import dotted hanya menavigasi pohon ini:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// main.rp</span></span>
<span class="line"><span>import v from ./rpx_engine</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(v.view.resources.id)      // ✅ terjangkau lewat rantai index</span></span>
<span class="line"><span>print(v.view.resources.load)    // undefined — private di edge index</span></span></code></pre></div><p>Dua jaminan runtime:</p><ul><li><strong>Eksekusi sekali</strong> — module yang sama hanya dieksekusi satu kali per run program, berapa kali pun dan dari jalur mana pun di-export ulang.</li><li><strong>Import tidak bocor</strong> — binding hasil <code>import</code> di dalam sebuah file bukan milik module itu, jadi <strong>tidak ikut terekspos</strong> saat file di-publish sebagai module. Yang dilihat consumer hanya yang didefinisikan file tersebut.</li></ul><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// view/resources.rp</span></span>
<span class="line"><span>import fs, os from rupa         // konsumsi internal</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const id = &quot;res&quot;</span></span>
<span class="line"><span>load() { ... }</span></span></code></pre></div><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import v from ./rpx_engine</span></span>
<span class="line"><span>print(v.view.resources.fs)      // undefined — fs bukan milik resources</span></span>
<span class="line"><span>print(v.view.resources.id)      // &quot;res&quot;</span></span></code></pre></div><h2 id="aturan" tabindex="-1">Aturan <a class="header-anchor" href="#aturan" aria-label="Permalink to &quot;Aturan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Syntax</th><th>Keterangan</th></tr></thead><tbody><tr><td><code>export * from ./X</code></td><td><strong>Kanonik</strong> — semua member X di-flatten</td></tr><tr><td><code>export x, y from ./X</code></td><td><strong>Kanonik</strong> — selective: hanya <code>x</code> dan <code>y</code></td></tr><tr><td><code>export name from ./path</code></td><td>Member <code>name</code> bila ada, selain itu whole module</td></tr><tr><td><code>export name from ./path -&gt; { x: private }</code></td><td>Namespace <code>name</code>, <code>x</code> tidak bisa diakses</td></tr><tr><td><code>namespace c { export x from ./x }</code></td><td>Membentuk namespace <code>c</code> dari export di dalam body</td></tr></tbody></table><h2 id="error-cases" tabindex="-1">Error Cases <a class="header-anchor" href="#error-cases" aria-label="Permalink to &quot;Error Cases&quot;">​</a></h2><ul><li><strong>Module tanpa export</strong>: Jika file tidak memiliki <code>export</code>, <code>import</code> menghasilkan <code>ImportError: Module &#39;&lt;path&gt;&#39; does not export anything — nothing to import</code>.</li><li><strong>Member tidak di-export</strong>: <code>import x from ./mod</code> saat <code>x</code> tidak di-export module menghasilkan <code>ImportError: Member &#39;x&#39; not found in module &#39;./mod&#39;</code>.</li><li><strong>Module tidak ditemukan</strong>: <code>import x from ./tidakada</code> menghasilkan <code>ImportError: Import failed for &#39;x&#39; from &#39;./tidakada&#39;</code>.</li><li><strong>Dotted path melompati pohon</strong>: <code>import z from ./pkg.z</code> saat tidak ada <code>pkg.z</code> di rantai index menghasilkan <code>ImportError</code> — import dotted hanya menavigasi cabang yang benar-benar ada di pohon package.</li><li><strong>File leaf diakses langsung dari luar package</strong>: import langsung ke file internal package ditolak — aksesnya harus melalui index package-nya.</li><li><strong>Import private item</strong>: Jika mencoba memanggil item yang di-mark <code>private</code>, muncul <code>PrivateError: &#39;&lt;name&gt;&#39; is private and cannot be called from outside</code>.</li><li><strong>Bentuk warisan</strong>: bare import (<code>import X</code>), bare export (<code>export x</code>), member chain (<code>import x.y</code>), wildcard member (<code>import x.*</code>), entry alias (<code>import x as y</code>), dan source alias (<code>from X as m</code>) bukan bagian dari grammar — baris seperti itu tidak memproduksi import/export dan diabaikan seperti statement tak dikenal.</li></ul><h2 id="path-resolution" tabindex="-1">Path Resolution <a class="header-anchor" href="#path-resolution" aria-label="Permalink to &quot;Path Resolution&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Resolves to</th></tr></thead><tbody><tr><td><code>./modules.a</code></td><td><code>./modules/a.rp</code></td></tr><tr><td><code>./modules</code></td><td><code>./modules/*.rp</code></td></tr><tr><td><code>rupa</code></td><td>stdlib module</td></tr></tbody></table>`,44)])])}const h=e(p,[["render",i]]);export{m as __pageData,h as default};
